<?php
declare(strict_types=1); require_once __DIR__.'/includes/auth.php'; require_once __DIR__.'/includes/csrf.php'; require_once __DIR__.'/connection.php'; require_alumni();
$email=$_SESSION['user_email']; $message=''; $type=''; $data=['first_name'=>$_SESSION['first_name']??'','middle_name'=>$_SESSION['middle_name']??'','last_name'=>$_SESSION['last_name']??'','birthdate'=>'','phone'=>'','address'=>'','city'=>'','gender'=>'','civil_status'=>'','course'=>$_SESSION['course']??'','batch_year'=>$_SESSION['batch_year']??''];
$stmt=mysqli_prepare($connection,'SELECT * FROM alumni_profiles WHERE email=? LIMIT 1'); if($stmt){mysqli_stmt_bind_param($stmt,'s',$email);mysqli_stmt_execute($stmt);$row=mysqli_fetch_assoc(mysqli_stmt_get_result($stmt))?:[];foreach($data as $k=>$v)if(isset($row[$k]))$data[$k]=$row[$k];mysqli_stmt_close($stmt);}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();foreach($data as $k=>$v)$data[$k]=trim($_POST[$k]??'');if($data['first_name']===''||$data['last_name']===''){$message='First and last name are required.';$type='danger';}else{$sql='INSERT INTO alumni_profiles(email,first_name,middle_name,last_name,birthdate,phone,address,city,gender,civil_status,course,batch_year) VALUES(?,?,?,?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE first_name=VALUES(first_name),middle_name=VALUES(middle_name),last_name=VALUES(last_name),birthdate=VALUES(birthdate),phone=VALUES(phone),address=VALUES(address),city=VALUES(city),gender=VALUES(gender),civil_status=VALUES(civil_status),course=VALUES(course),batch_year=VALUES(batch_year)';$stmt=mysqli_prepare($connection,$sql);if($stmt){mysqli_stmt_bind_param($stmt,'ssssssssssss',$email,...array_values($data));mysqli_stmt_execute($stmt);mysqli_stmt_close($stmt);$_SESSION['first_name']=$data['first_name'];$_SESSION['last_name']=$data['last_name'];$message='Profile saved successfully.';$type='success';}}}
$pageTitle='My Profile';?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Profile | AlumTrace</title><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css"><link rel="stylesheet" href="assets/css/alumtrace.css"></head><body><?php require __DIR__.'/includes/sidebar.php';?><div class="main-wrapper"><?php require __DIR__.'/includes/topbar.php';?><main class="content"><div class="page-head"><h2>My Profile</h2><p>Keep your identity, contact, and academic information current.</p></div><?php if($message):?><div class="alert alert-<?= $type ?>"><?=htmlspecialchars($message)?></div><?php endif;?><div class="panel"><form method="post"><?=csrf_field()?><div class="fields cols-3"><?php foreach(['first_name'=>'First name','middle_name'=>'Middle name','last_name'=>'Last name'] as $k=>$label):?><div class="field"><label><?=htmlspecialchars($label)?></label><input class="input" name="<?=$k?>" value="<?=htmlspecialchars($data[$k])?>" <?= $k!=='middle_name'?'required':'' ?>></div><?php endforeach;?></div><div class="fields cols-2"><?php foreach(['birthdate'=>'Birthdate','phone'=>'Phone','city'=>'City','course'=>'Course','batch_year'=>'Batch year'] as $k=>$label):?><div class="field"><label><?=htmlspecialchars($label)?></label><input class="input" name="<?=$k?>" type="<?= $k==='birthdate'?'date':'text' ?>" value="<?=htmlspecialchars($data[$k])?>"></div><?php endforeach;?></div><div class="field"><label>Address</label><textarea class="textarea" name="address"><?=htmlspecialchars($data['address'])?></textarea></div><div class="fields cols-2"><div class="field"><label>Gender</label><select class="select" name="gender"><option value="">Select</option><?php foreach(['Male','Female','Prefer not to say'] as $v):?><option <?=$data['gender']===$v?'selected':''?>><?=$v?></option><?php endforeach;?></select></div><div class="field"><label>Civil status</label><select class="select" name="civil_status"><option value="">Select</option><?php foreach(['Single','Married','Widowed','Separated','Divorced'] as $v):?><option <?=$data['civil_status']===$v?'selected':''?>><?=$v?></option><?php endforeach;?></select></div></div><button class="btn btn-primary" type="submit"><i class="fa-solid fa-floppy-disk"></i> Save profile</button></form></div></main><?php require __DIR__.'/includes/dashboard-footer.php';?></div><script src="assets/js/alumtrace.js"></script></body></html>
